scripts.goals-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'goals-store',
  description:
    "Read and update the team's goals (goals.json), their key results (keyresults.json), weekly check-ins (checkins.json) and meeting actions (actions.json). action:'status' for the whole picture; 'add_goal' and 'add_key_result' save one (an existing title is updated, never duplicated); 'update_key_result' records progress (change is added to the current value, value replaces it); 'set_goal_status' closes or reopens a goal; 'checkin' logs a weekly check-in; 'add_action' and 'complete_action' keep the meeting actions.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'add_goal', 'add_key_result', 'update_key_result', 'set_goal_status', 'checkin', 'add_action', or 'complete_action'.",
      required: true,
    },
    goal: { type: 'string', description: "A goal's id ('g-2') or (part of) its title." },
    keyResult: { type: 'string', description: "A key result's id ('kr-3') or (part of) its title." },
    id: { type: 'string', description: "A meeting action's id, e.g. 'act-2'." },
    title: {
      type: 'string',
      description: "The title of the goal, key result or action being saved, e.g. 'Win four new retainer clients'.",
    },
    owner: { type: 'string', description: 'Who owns it.' },
    startAt: { type: 'string', description: 'When a goal started, YYYY-MM-DD (default today).' },
    dueAt: { type: 'string', description: 'When it is due, YYYY-MM-DD.' },
    start: { type: 'number', description: 'Where a key result started.' },
    current: { type: 'number', description: 'Where a key result stands now.' },
    target: { type: 'number', description: 'Where a key result should end up.' },
    unit: { type: 'string', description: "What a key result counts: 'clients', '%', '$', 'hours'." },
    change: {
      type: 'number',
      description: 'How much a key result moved: 2 for two more, -1 for one fewer. Added to its current value.',
    },
    value: { type: 'number', description: "A key result's new total, only when the person gives the total." },
    how: { type: 'string', description: "The page form's choice between change and value; the script reads change or value." },
    who: { type: 'string', description: 'Who is checking in.' },
    confidence: { type: 'string', description: 'on-track, at-risk, or off-track.' },
    status: { type: 'string', description: 'For set_goal_status: active, done, or dropped.' },
    from: { type: 'string', description: "The meeting an action came from, e.g. 'Monday team meeting'." },
    note: { type: 'string', description: 'What happened, in their words.' },
  },
  outputs: {
    active: { type: 'number', description: 'Active goals.' },
    offPace: { type: 'number', description: 'Active goals at risk, behind or past due.' },
    openActions: { type: 'number', description: 'Meeting actions still open.' },
    summary: {
      type: 'string',
      description: 'What changed first, then every active goal (furthest behind first) with its key results, the check-ins and the open actions.',
    },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── goals-rules-start ──
// Pure derivations: key-result progress (current against target, from where it
// started), a goal's pace against the share of its time already gone, the
// week's check-ins, and the lines the crew reads. Kept self-contained between
// these sentinels so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var STOP_WORDS = ['the', 'and', 'for', 'our', 'with', 'from', 'that', 'this', 'into', 'more'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function dayMs(day) {
  return Date.parse(String(day).slice(0, 10) + 'T00:00:00');
}
function daysLeft(dueAt, nowMs) {
  return Math.round((dayMs(dueAt) - dayMs(localDay(nowMs))) / DAY_MS);
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'due today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function round2(n) {
  return Math.round(n * 100) / 100;
}
function fmt(n) {
  var r = round2(Number(n) || 0);
  var parts = String(Math.abs(r)).split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (r < 0 ? '-' : '') + parts.join('.');
}
function amount(n, unit) {
  var u = String(unit || '').trim();
  if (u === '%' || /^percent/i.test(u)) return fmt(n) + '%';
  if (u === '$' || /^(dollars?|usd)$/i.test(u)) return '$' + fmt(n);
  if (fmt(n) === '1' && /^[a-z]+[^su]s$/i.test(u)) u = u.slice(0, -1);
  return fmt(n) + (u ? ' ' + u : '');
}
function percent(p) {
  return Math.round(p * 100) + '%';
}
function normalizeConfidence(text) {
  var t = String(text || '').trim().toLowerCase().replace(/[\s_]+/g, '-');
  if (/^(on-?track|green|good|fine)/.test(t)) return 'on-track';
  if (/^(at-?risk|amber|yellow|watch|shaky|unsure)/.test(t)) return 'at-risk';
  if (/^(off-?track|behind|red|blocked|stuck|slipping)/.test(t)) return 'off-track';
  return null;
}
function normalizeGoalStatus(text) {
  var t = String(text || '').trim().toLowerCase();
  if (/^(active|open|reopen|restart|resume)/.test(t)) return 'active';
  if (/^(done|complete|finished|met|achieved|closed)/.test(t)) return 'done';
  if (/^(dropped|drop|cancel|abandon|parked|shelved)/.test(t)) return 'dropped';
  return null;
}
// How far a key result has come from where it started toward its target, 0..1.
// A target below the start (fewer overdue invoices) counts down the same way.
function krProgress(f) {
  var start = Number(f.start) || 0;
  var target = Number(f.target);
  var current = Number(f.current) || 0;
  if (!isFinite(target)) return 0;
  if (target === start) return current >= target ? 1 : 0;
  return Math.max(0, Math.min(1, (current - start) / (target - start)));
}
// The share of a goal's window already gone, 0..1, or null without a due date.
function timeGone(f, nowMs) {
  var due = dayMs(f.dueAt || '');
  if (!isFinite(due)) return null;
  var start = dayMs(f.startAt || '');
  var today = dayMs(localDay(nowMs));
  if (!isFinite(start) || due <= start) return today >= due ? 1 : 0;
  return Math.max(0, Math.min(1, (today - start) / (due - start)));
}
function pace(progress, gone) {
  if (progress === null) return 'no key results yet';
  if (progress >= 1) return 'target met';
  if (gone === null) return 'no due date';
  if (gone >= 1) return 'past due';
  if (progress >= gone - 0.1) return 'on track';
  if (progress >= gone - 0.25) return 'at risk';
  return 'behind';
}
function titleOf(record) {
  return String((record && record.fields && record.fields.title) || '');
}
function goalKeyResults(goal, krs) {
  return krs.filter(function (k) {
    return k.fields && k.fields.goalId === goal.id && k.status !== 'closed';
  });
}
function goalProgress(goal, krs) {
  var mine = goalKeyResults(goal, krs);
  if (!mine.length) return null;
  return (
    mine.reduce(function (sum, k) {
      return sum + krProgress(k.fields);
    }, 0) / mine.length
  );
}
// How far behind its time a goal is: the gap the board sorts by, worst first.
function lag(goal, krs, nowMs) {
  var p = goalProgress(goal, krs);
  var gone = timeGone(goal.fields || {}, nowMs);
  if (p === null) return -2;
  if (gone === null) return -1;
  return gone - p;
}
function krLine(k) {
  var f = k.fields || {};
  var from = Number(f.start) || 0;
  return (
    k.id + ' ' + f.title + ': now ' + amount(f.current || 0, f.unit) + ', target ' + amount(f.target, f.unit) +
    (from ? ' (started at ' + amount(from, f.unit) + ')' : '') + ', ' + percent(krProgress(f)) + ' of the way'
  );
}
function lastCheckin(goal, events) {
  var mine = events.filter(function (e) {
    return e.kind === 'checkin' && e.data && e.data.goalId === goal.id;
  });
  return mine.length ? mine[mine.length - 1] : null;
}
function checkedInSince(goal, events, sinceMs) {
  var owner = String((goal.fields && goal.fields.owner) || '').trim().toLowerCase();
  return events.some(function (e) {
    if (e.kind !== 'checkin' || !e.data || Date.parse(e.at) < sinceMs) return false;
    if (e.data.goalId) return e.data.goalId === goal.id;
    return !!owner && String(e.data.who || '').trim().toLowerCase() === owner;
  });
}
function goalLine(goal, krs, events, nowMs) {
  var f = goal.fields || {};
  var p = goalProgress(goal, krs);
  var gone = timeGone(f, nowMs);
  var mine = goalKeyResults(goal, krs);
  var last = lastCheckin(goal, events);
  return (
    goal.id + ' ' + f.title + ' (owner ' + (f.owner || 'unassigned') +
    (f.dueAt ? ', due ' + f.dueAt + ', ' + when(daysLeft(f.dueAt, nowMs)) : '') + '): ' +
    (p === null ? 'no key results yet' : percent(p) + ' done' + (gone === null ? '' : ' with ' + percent(gone) + ' of the time gone') + ', ' + pace(p, gone)) +
    (mine.length ? '. Key results: ' + mine.map(krLine).join('; ') : '') + '. ' +
    (last
      ? 'Last check-in ' + localDay(Date.parse(last.at)) + (last.data.who ? ' by ' + last.data.who : '') +
        (last.data.confidence ? ', ' + String(last.data.confidence).replace('-', ' ') : '') + (last.note ? ': ' + String(last.note).replace(/[.!?\s]+$/, '') : '')
      : 'No check-in yet') + '.'
  );
}
function actionLine(a, nowMs) {
  var f = a.fields || {};
  return a.id + ' ' + f.title + ' (' + (f.owner || 'no owner') + (f.dueAt ? ', due ' + f.dueAt + ', ' + when(daysLeft(f.dueAt, nowMs)) : '') + ')';
}
function picture(goals, krs, events, actions, nowMs) {
  var active = goals
    .filter(function (g) { return g.status === 'active'; })
    .sort(function (a, b) { return lag(b, krs, nowMs) - lag(a, krs, nowMs); });
  var paces = active.map(function (g) { return pace(goalProgress(g, krs), timeGone(g.fields || {}, nowMs)); });
  var offPace = paces.filter(function (p) { return p === 'at risk' || p === 'behind' || p === 'past due'; }).length;
  var onTrack = paces.filter(function (p) { return p === 'on track' || p === 'target met'; }).length;
  var open = actions
    .filter(function (a) { return a.status !== 'done'; })
    .sort(function (a, b) { return String(a.fields.dueAt || '9999').localeCompare(String(b.fields.dueAt || '9999')); });
  var since = dayMs(localDay(nowMs)) - 6 * DAY_MS;
  var quiet = active.filter(function (g) { return !checkedInSince(g, events, since); });
  var parts = [];
  parts.push(
    active.length
      ? active.length + (active.length === 1 ? ' active goal: ' : ' active goals: ') + onTrack + ' on track, ' + offPace + ' at risk or behind.' +
          (active.length > 1 ? ' Goals, furthest behind first:' : '')
      : goals.length ? 'No active goals.' : 'No active goals yet.',
  );
  active.forEach(function (g) { parts.push(goalLine(g, krs, events, nowMs)); });
  if (active.length) {
    parts.push(
      quiet.length
        ? 'No check-in in the last 7 days: ' + quiet.map(function (g) { return (g.fields.owner || 'unassigned') + ' for ' + g.id + ' ' + g.fields.title; }).join('; ') + '.'
        : 'Every active goal has a check-in from the last 7 days.',
    );
  }
  parts.push(open.length ? 'Open actions, late ones first, then soonest due: ' + open.map(function (a) { return actionLine(a, nowMs); }).join('; ') + '.' : 'No open meeting actions.');
  var closed = goals.filter(function (g) { return g.status !== 'active'; });
  if (closed.length) parts.push('Closed goals: ' + closed.map(function (g) { return g.id + ' ' + g.fields.title + ' (' + g.status + ')'; }).join('; ') + '.');
  return { active: active.length, offPace: offPace, openActions: open.length, summary: parts.join(' ') };
}
// Find one record by id, exact title, partial title, or every word of the
// title; a miss lists what there is so the next call can name it.
function pick(records, wanted, label) {
  var text = String(wanted || '').trim();
  var lower = text.toLowerCase();
  if (!lower) throw new Error('Name the ' + label + ' by its id or title.');
  var byId = records.filter(function (r) { return r.id === lower; });
  if (byId.length) return byId[0];
  var exact = records.filter(function (r) { return titleOf(r).toLowerCase() === lower; });
  if (exact.length === 1) return exact[0];
  var partial = records.filter(function (r) { return titleOf(r).toLowerCase().indexOf(lower) >= 0; });
  if (partial.length === 1) return partial[0];
  if (!partial.length) {
    var words = (lower.match(/[a-z0-9]{3,}/g) || []).filter(function (w) { return STOP_WORDS.indexOf(w) < 0; });
    partial = words.length
      ? records.filter(function (r) {
          var t = titleOf(r).toLowerCase();
          return words.every(function (w) { return t.indexOf(w) >= 0 || t.indexOf(w.replace(/ies$/, 'y').replace(/s$/, '')) >= 0; });
        })
      : [];
    if (partial.length === 1) return partial[0];
  }
  var known = (partial.length > 1 ? partial : records).map(function (r) { return r.id + ' ' + titleOf(r); }).join(', ');
  throw new Error(
    (partial.length > 1 ? 'More than one ' + label + " matches '" + text + "': " : 'No ' + label + " matches '" + text + "'. Known: ") +
      (known || 'none yet') + '. Pass the id.',
  );
}
function pickPreferring(preferred, all, wanted, label) {
  try {
    return pick(preferred, wanted, label);
  } catch (error) {
    return pick(all, wanted, label);
  }
}
// ── goals-rules-end ──

const goals = rosterStore(gezel.fs, 'goals.json', { stages: ['active', 'done', 'dropped'], idPrefix: 'g' });
const keyResults = rosterStore(gezel.fs, 'keyresults.json', { stages: ['active', 'closed'], idPrefix: 'kr' });
const checkins = logStore(gezel.fs, 'checkins.json');
const actions = rosterStore(gezel.fs, 'actions.json', { stages: ['open', 'done'], idPrefix: 'act' });

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}
function dateInput(value: unknown, name: string): string | null {
  if (!text(value)) return null;
  const day = normalizeDate(value);
  if (!day) throw new Error(name + " must be a date, e.g. '2026-12-31'.");
  return day;
}
async function findGoal(wanted: string) {
  const all = await goals.list();
  return pickPreferring(all.filter((g) => g.status === 'active'), all, wanted, 'goal');
}

const now = Date.now();
let note = '';

if (input.action === 'add_goal') {
  const title = text(input.title) || text(input.goal);
  if (!title) throw new Error("add_goal needs 'title', e.g. 'Win four new retainer clients'.");
  const dueAt = dateInput(input.dueAt, 'dueAt');
  const startAt = dateInput(input.startAt, 'startAt');
  const fields: Record<string, unknown> = {
    ...(dueAt ? { dueAt } : {}),
    ...(startAt ? { startAt } : {}),
    ...(text(input.owner) ? { owner: text(input.owner) } : {}),
    ...(text(input.note) ? { why: text(input.note) } : {}),
  };
  const existing = (await goals.list()).find((g) => titleOf(g).toLowerCase() === title.toLowerCase());
  if (existing) {
    await goals.update(existing.id, { fields });
    note = 'Updated ' + existing.id + ' ' + titleOf(existing) + '.';
  } else {
    const record = await goals.add({ status: 'active', fields: { title, startAt: startAt ?? localDay(now), ...fields } });
    note = 'Added ' + record.id + ' ' + title + (dueAt ? ', due ' + dueAt : '') + '.';
  }
} else if (input.action === 'add_key_result') {
  if (!text(input.goal)) throw new Error("add_key_result needs 'goal' (its id or title) and 'title'.");
  const goal = await findGoal(text(input.goal));
  const title = text(input.title) || text(input.keyResult);
  if (!title) throw new Error("add_key_result needs 'title', e.g. 'New retainer clients'.");
  const unit = text(input.unit);
  const existing = (await keyResults.list()).find(
    (k) => k.fields.goalId === goal.id && titleOf(k).toLowerCase() === title.toLowerCase(),
  );
  const fields: Record<string, unknown> = {
    ...(typeof input.target === 'number' ? { target: round2(input.target) } : {}),
    ...(typeof input.current === 'number' ? { current: round2(input.current) } : {}),
    ...(typeof input.start === 'number' ? { start: round2(input.start) } : {}),
    ...(unit ? { unit } : {}),
  };
  if (existing) {
    await keyResults.update(existing.id, { fields, note: 'Edited.' });
    note = 'Updated ' + existing.id + ' ' + titleOf(existing) + '.';
  } else {
    if (typeof input.target !== 'number') throw new Error("A new key result needs 'target', the number it should reach.");
    const start = typeof input.start === 'number' ? input.start : typeof input.current === 'number' ? input.current : 0;
    const current = typeof input.current === 'number' ? input.current : start;
    const record = await keyResults.add({
      status: goal.status === 'active' ? 'active' : 'closed',
      fields: { goalId: goal.id, goal: titleOf(goal), title, start: round2(start), current: round2(current), target: round2(input.target), ...(unit ? { unit } : {}) },
    });
    note = 'Added ' + record.id + ' ' + title + ' to ' + goal.id + ': now ' + amount(current, unit) + ', target ' + amount(input.target, unit) + '.';
  }
} else if (input.action === 'update_key_result') {
  const all = await keyResults.list();
  let pool = all;
  if (text(input.goal)) {
    const goal = await findGoal(text(input.goal));
    pool = all.filter((k) => k.fields.goalId === goal.id);
  }
  const wanted = text(input.keyResult) || text(input.title);
  let kr;
  if (wanted) kr = pickPreferring(pool.filter((k) => k.status !== 'closed'), all, wanted, 'key result');
  else if (pool !== all && pool.length === 1) kr = pool[0]!;
  else {
    throw new Error(
      "update_key_result needs 'keyResult' (its id or title). Known: " +
        (pool.map((k) => k.id + ' ' + titleOf(k)).join(', ') || 'none yet') + '.',
    );
  }
  const change = typeof input.change === 'number' ? input.change : null;
  const value = typeof input.value === 'number' ? input.value : null;
  if (change === null && value === null) {
    throw new Error("update_key_result needs 'change' (how much it moved: 2, or -1) or 'value' (the new total).");
  }
  const before = Number(kr.fields.current) || 0;
  const after = round2(change !== null ? before + change : (value as number));
  const unit = String(kr.fields.unit ?? '');
  await keyResults.update(kr.id, {
    fields: { current: after },
    note: fmt(before) + ' to ' + fmt(after) + (text(input.note) ? ': ' + text(input.note) : ''),
  });
  await checkins.append({
    kind: 'progress',
    ...(text(input.note) ? { note: text(input.note) } : {}),
    data: { goalId: kr.fields.goalId, keyResultId: kr.id, from: before, to: after, ...(text(input.who) ? { who: text(input.who) } : {}) },
  });
  note =
    titleOf(kr) + ' moved from ' + amount(before, unit) + ' to ' + amount(after, unit) + ' (target ' + amount(kr.fields.target, unit) + ', ' +
    percent(krProgress({ ...kr.fields, current: after })) + ' of the way).';
} else if (input.action === 'set_goal_status') {
  const status = normalizeGoalStatus(input.status);
  if (!status) throw new Error("set_goal_status needs status 'active', 'done', or 'dropped'.");
  if (!text(input.goal)) throw new Error("set_goal_status needs 'goal' (its id or title).");
  const goal = pick(await goals.list(), text(input.goal), 'goal');
  if (goal.status !== status) await goals.transition(goal.id, status, text(input.note) ? { note: text(input.note) } : {});
  for (const k of await keyResults.list()) {
    if (k.fields.goalId !== goal.id) continue;
    const next = status === 'active' ? 'active' : 'closed';
    if (k.status !== next) await keyResults.transition(k.id, next);
  }
  note = titleOf(goal) + (status === 'active' ? ' is active again.' : status === 'done' ? ' is done.' : ' was dropped.');
} else if (input.action === 'checkin') {
  const confidence = text(input.confidence) ? normalizeConfidence(input.confidence) : null;
  if (text(input.confidence) && !confidence) throw new Error("confidence must be 'on-track', 'at-risk', or 'off-track'.");
  if (!text(input.note) && !confidence) throw new Error("A check-in needs 'note' (what they said) or 'confidence'.");
  const goal = text(input.goal) ? await findGoal(text(input.goal)) : null;
  const who = text(input.who) || (goal ? String(goal.fields.owner ?? '') : '');
  await checkins.append({
    kind: 'checkin',
    ...(text(input.note) ? { note: text(input.note) } : {}),
    data: { ...(goal ? { goalId: goal.id } : {}), ...(who ? { who } : {}), ...(confidence ? { confidence } : {}) },
  });
  note =
    'Logged ' + (who ? who + "'s check-in" : 'a check-in') + (goal ? ' on ' + titleOf(goal) : '') +
    (confidence ? ': ' + confidence.replace('-', ' ') : '') + '.';
} else if (input.action === 'add_action') {
  const title = text(input.title);
  if (!title) throw new Error("add_action needs 'title', e.g. 'Send Alder Co the proposal'.");
  const dueAt = dateInput(input.dueAt, 'dueAt');
  let goalId = '';
  let unlinked = '';
  if (text(input.goal)) {
    try {
      goalId = (await findGoal(text(input.goal))).id;
    } catch {
      unlinked = " No goal matched '" + text(input.goal) + "', so it is not linked to one.";
    }
  }
  const fields: Record<string, unknown> = {
    ...(text(input.owner) ? { owner: text(input.owner) } : {}),
    ...(dueAt ? { dueAt } : {}),
    ...(goalId ? { goalId } : {}),
    ...(text(input.from) ? { from: text(input.from) } : {}),
  };
  const existing = (await actions.list()).find((a) => a.status !== 'done' && titleOf(a).toLowerCase() === title.toLowerCase());
  if (existing) {
    await actions.update(existing.id, { fields });
    note = 'Updated ' + existing.id + ' ' + titleOf(existing) + '.' + unlinked;
  } else {
    const record = await actions.add({ status: 'open', fields: { title, ...fields } });
    note = 'Added ' + record.id + ' ' + title + (text(input.owner) ? ' for ' + text(input.owner) : '') + (dueAt ? ', due ' + dueAt : '') + '.' + unlinked;
  }
} else if (input.action === 'complete_action') {
  const wanted = text(input.id) || text(input.title);
  if (!wanted) throw new Error("complete_action needs 'id' (e.g. 'act-2') or the action's 'title'.");
  const all = await actions.list();
  const done = pickPreferring(all.filter((a) => a.status !== 'done'), all, wanted, 'action');
  if (done.status !== 'done') await actions.transition(done.id, 'done', text(input.note) ? { note: text(input.note) } : {});
  note = 'Done: ' + titleOf(done) + (done.fields.owner ? ' (' + String(done.fields.owner) + ')' : '') + '.';
} else if (input.action !== 'status') {
  throw new Error(
    "Unknown action '" + input.action + "'. Use status, add_goal, add_key_result, update_key_result, set_goal_status, checkin, add_action, or complete_action.",
  );
}

const view = picture(await goals.list(), await keyResults.list(), await checkins.list(), await actions.list(), Date.now());

gezel.output({
  active: view.active,
  offPace: view.offPace,
  openActions: view.openActions,
  summary: (note ? note + ' ' : '') + view.summary,
});

